INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Masalah: Ingin Menyalakan Lampu Otomatis tapi Arduino Tidak Kuat$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Arduino hanya mampu memberi arus kecil (sekitar 20-40 mA per pin), jauh dari cukup untuk menyalakan lampu rumah, kipas, atau pompa air. Jika dipaksakan, pin Arduino bisa rusak permanen. Relay adalah solusinya: sebuah sakelar elektromagnetik yang dikendalikan sinyal kecil dari Arduino tetapi mampu memutus-menyambung arus besar di sisi lain.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Penjelasan: Cara Kerja Relay$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Di dalam relay ada kumparan (koil) dan kontak logam. Saat Arduino memberi tegangan 5V ke koil, timbul medan magnet yang menarik kontak sehingga rangkaian beban tersambung (bunyi "klik" khas relay). Saat sinyal dimatikan, pegas mengembalikan kontak ke posisi semula. Bagian kendali dan bagian beban terisolasi secara elektrik, sehingga Arduino tetap aman.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Alat dan Bahan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$Arduino Uno/Nano$t$, $t$Modul relay 1 channel 5V (dengan optocoupler)$t$, $t$Lampu LED + baterai 9V untuk latihan aman, atau lampu AC untuk tahap lanjut$t$, $t$Kabel jumper secukupnya$t$, $t$Komputer dengan Arduino IDE$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Langkah: Merangkai Modul Relay$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$t$Hubungkan VCC modul relay ke 5V Arduino, GND ke GND, dan pin IN ke pin digital 7.$t$, $t$Untuk latihan, sambungkan beban DC kecil (LED + baterai) ke terminal COM dan NO (Normally Open) relay.$t$, $t$Upload sketch sederhana: digitalWrite(7, HIGH) untuk menyalakan, LOW untuk mematikan, dengan jeda 2 detik.$t$, $t$Dengarkan bunyi klik relay setiap kali status berubah — itu tanda kontak bekerja.$t$, $t$Coba ganti jeda dengan sensor: misalnya relay menyala saat sensor cahaya mendeteksi gelap.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Risiko dan Keselamatan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$t$PERINGATAN: jangan menyentuh terminal relay saat terhubung ke listrik AC 220V — bahaya sengatan listrik yang fatal.$t$, $t$Untuk pemula, berlatihlah hanya dengan beban DC tegangan rendah (baterai) sampai benar-benar paham.$t$, $t$Pastikan rating relay (misalnya 10A 250VAC) lebih besar dari arus beban yang dikendalikan.$t$, $t$Jangan membalik polaritas koil pada relay tanpa modul; gunakan modul relay jadi yang sudah ada diodanya.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Pemeriksaan Hasil dan Tindak Lanjut$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $t$Lampu latihan harus menyala dan mati mengikuti perintah sketch dengan bunyi klik yang jelas dari relay. Ukur dengan multimeter di terminal COM-NO: saat aktif harus tersambung (0 ohm), saat mati harus terputus. Jika relay bergetar atau LED modul tidak menyala, periksa kabel VCC dan GND. Setelah mahir dengan beban DC, kembangkan menjadi lampu taman otomatis dengan sensor cahaya (LDR) atau penyiram tanaman otomatis dengan sensor kelembapan. Untuk beban AC rumah tangga, mintalah pendampingan orang dewasa yang paham instalasi listrik.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Masalah: Bumbu Kacang Ketoprak Kurang Medok$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Ketoprak yang enak ditentukan oleh bumbu kacangnya: harus kental, gurih, pedasnya pas, dan beraroma bawang putih. Bumbu yang encer atau hambar membuat seluruh hidangan terasa datar. Kuncinya ada pada kacang tanah yang digoreng sempurna dan pengulekan yang benar-benar halus.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Penjelasan: Ciri Khas Ketoprak Jakarta$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Ketoprak adalah jajanan kaki lima legendaris Jakarta berisi bihun, tahu goreng, tauge rebus, ketupat atau lontong, disiram bumbu kacang lalu ditaburi kerupuk dan bawang goreng. Berbeda dengan gado-gado yang bumbunya dimasak, bumbu ketoprak diulek mentah sehingga aromanya lebih segar dan tajam.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Bahan (untuk 4 porsi)$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$200 gram bihun, seduh air panas lalu tiriskan$t$, $t$2 buah tahu putih, goreng hingga berkulit lalu potong dadu$t$, $t$150 gram tauge, seduh air panas sebentar$t$, $t$2 buah ketupat atau lontong, potong-potong$t$, $t$150 gram kacang tanah goreng$t$, $t$3 siung bawang putih$t$, $t$5 buah cabai rawit (sesuai selera)$t$, $t$1 sendok teh garam$t$, $t$1 sendok makan gula merah serut$t$, $t$2 sendok makan air asam jawa$t$, $t$Kecap manis, kerupuk, dan bawang goreng untuk taburan$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Langkah Membuat$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$t$Ulek kacang tanah goreng, bawang putih, cabai rawit, garam, dan gula merah hingga benar-benar halus.$t$, $t$Tambahkan air asam jawa dan sedikit air matang, aduk hingga menjadi saus kental. Koreksi rasa: gurih, manis, asam, dan pedas harus seimbang.$t$, $t$Tata di piring: ketupat, bihun, tahu goreng, dan tauge.$t$, $t$Siram dengan bumbu kacang secukupnya, tambahkan kecap manis sesuai selera.$t$, $t$Taburi kerupuk yang diremuk dan bawang goreng. Sajikan segera agar kerupuk tetap renyah.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Risiko dan Kesalahan Umum$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$t$Bumbu encer: kurangi air, tambahkan kacang yang diulek lagi hingga kental.$t$, $t$Kacang gosong saat menggoreng: gunakan api kecil dan aduk terus; kacang gosong membuat bumbu pahit.$t$, $t$Tauge terlalu lembek: cukup diseduh air panas 1-2 menit, jangan direbus lama.$t$, $t$Bumbu cepat basi: karena mentah, habiskan dalam sehari atau simpan di kulkas maksimal 2 hari.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Penyajian dan Variasi$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $t$Sajikan ketoprak selagi hangat dengan kerupuk putih atau emping. Untuk variasi, tambahkan telur rebus atau perkedel. Di Jakarta, ketoprak biasa dijual gerobak dengan porsi jumbo — jangan ragu menambah porsi bihun dan tahunya untuk makan siang yang mengenyangkan.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Logam Merah Penopang Listrik Dunia$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Tembaga (Cu, nomor atom 29) adalah logam berwarna merah kecokelatan yang menjadi penghantar listrik terbaik kedua setelah perak. Hampir semua kabel listrik di rumah, motor listrik, dan perangkat elektronik memakai tembaga karena kombinasi daya hantar tinggi, kelenturan, dan harga yang lebih murah dari perak.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Sifat Istimewa Tembaga$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Tembaga mudah dibentuk menjadi kawat tipis tanpa putus (duktil) dan mudah ditempa (malleabel). Ia juga tahan korosi karena membentuk lapisan oksida pelindung berwarna kehijauan yang disebut patina — itulah sebabnya patung Liberty berwarna hijau. Sifat antimikrobanya membuat gagang pintu rumah sakit kadang dilapisi tembaga.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Dari Mana Tembaga Berasal$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $t$Tembaga ditambang dari bijih seperti kalkopirit, lalu dimurnikan lewat peleburan dan elektrolisis hingga kemurnian 99,99 persen. Indonesia memiliki tambang tembaga raksasa di Papua yang termasuk penghasil tembaga terbesar di dunia. Bijih tembaga sering ditemukan bersama emas dan perak.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Peran dalam Peradaban Manusia$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $t$Tembaga adalah logam pertama yang diolah manusia sekitar 10.000 tahun lalu, membuka Zaman Tembaga. Campurannya dengan timah menghasilkan perunggu yang lebih keras, lalu dengan seng menjadi kuningan. Tanpa tembaga, tidak ada jaringan listrik, telekomunikasi, kendaraan listrik, maupun energi terbarukan modern.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Daur Ulang dan Masa Depan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $t$Tembaga termasuk logam yang paling banyak didaur ulang: kualitasnya tidak menurun meski dilebur berkali-kali, dan mendaur ulang menghemat energi hingga 85 persen dibanding menambang baru. Dengan maraknya mobil listrik dan panel surya, kebutuhan tembaga dunia diprediksi terus melonjak.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Awal Mula Konflik$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Perang Padri (1803-1837) bermula sebagai konflik internal di Minangkabau antara kaum Padri — ulama yang pulang dari haji dan ingin memurnikan ajaran Islam — dengan kaum Adat yang mempertahankan tradisi lama. Ketegangan memuncak menjadi perang saudara sebelum Belanda ikut campur.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Tuanku Imam Bonjol$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Tokoh sentral kaum Padri adalah Tuanku Imam Bonjol (Muhammad Shahab), pemimpin karismatik dari Bonjol. Ia mengorganisasi pasukan, membangun benteng-benteng pertahanan, dan memimpin perlawanan selama belasan tahun. Namanya kini diabadikan sebagai pahlawan nasional Indonesia.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Belanda Masuk Arena$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $t$Kaum Adat yang terdesak meminta bantuan Belanda. Lewat Perjanjian Masang (1824), Belanda masuk dan mengubah perang saudara menjadi perang kolonial. Strategi Belanda adalah memecah belah: berdamai dengan satu pihak sambil menyerang pihak lain secara bergantian.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Benteng Bonjol Jatuh$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $t$Setelah perlawanan sengit, Belanda merebut Benteng Bonjol pada 1837 setelah pengepungan berbulan-bulan. Tuanku Imam Bonjol ditangkap melalui tipu muslihat perundingan, lalu diasingkan ke Cianjur, Ambon, hingga wafat di Manado pada 1864.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Dampak dan Warisan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $t$Perang Padri yang berlangsung 34 tahun menelan banyak korban dan mengubah tatanan Minangkabau. Namun ia juga melahirkan falsafah "Adat Basandi Syarak, Syarak Basandi Kitabullah" — perdamaian antara adat dan agama yang menjadi identitas Minangkabau hingga kini.$t$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Tujuan Pembelajaran$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Setelah mempelajari materi ini, peserta didik mampu menjelaskan pengertian modernisasi, mengidentifikasi ciri-ciri masyarakat modern, menganalisis faktor pendorong dan penghambat modernisasi, serta mengevaluasi dampak positif dan negatif modernisasi bagi masyarakat Indonesia.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Pengertian Modernisasi$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Modernisasi adalah proses perubahan masyarakat dari tradisional menuju modern yang ditandai oleh kemajuan ilmu pengetahuan dan teknologi. Menurut Soerjono Soekanto, modernisasi adalah perubahan sosial yang terarah (directed change) berdasarkan perencanaan. Modernisasi berbeda dengan westernisasi: modernisasi soal kemajuan cara berpikir dan teknologi, bukan meniru budaya Barat.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Ciri-Ciri Masyarakat Modern$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$t$Berpikir rasional dan ilmiah, tidak lagi mengandalkan takhayul.$t$, $t$Menghargai waktu, disiplin, dan efisiensi kerja.$t$, $t$Terbuka terhadap perubahan dan inovasi baru.$t$, $t$Sistem sosial lebih demokratis dan menghargai prestasi (achievement) dibanding keturunan.$t$, $t$Tingkat urbanisasi dan industrialisasi tinggi.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Faktor Pendorong Modernisasi$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$t$Kontak dengan budaya lain melalui perdagangan, media, dan migrasi.$t$, $t$Sistem pendidikan yang maju dan merata.$t$, $t$Pemerintahan yang stabil dan mendukung inovasi.$t$, $t$Penduduk yang heterogen sehingga toleran terhadap hal baru.$t$, $t$Ketidakpuasan terhadap kondisi lama yang mendorong perubahan.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Faktor Penghambat Modernisasi$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$t$Sikap tertutup dan curiga terhadap hal baru (xenofobia).$t$, $t$Adat istiadat yang mengikat kuat dan dianggap tidak boleh diubah.$t$, $t$Kepentingan kelompok yang merasa dirugikan oleh perubahan.$t$, $t$Tingkat pendidikan rendah sehingga sulit menerima teknologi.$t$, $t$Prasangka terhadap hal-hal asing tanpa penilaian objektif.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Latihan dan Kunci Jawaban$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$t$Latihan: 1. Jelaskan perbedaan modernisasi, westernisasi, dan sekularisasi! 2. Sebutkan tiga faktor penghambat modernisasi di daerah pedesaan beserta solusinya! 3. Analisis satu dampak positif dan satu dampak negatif media sosial sebagai wujud modernisasi!$t$, $t$Kunci: 1. Modernisasi = perubahan menuju kemajuan iptek; westernisasi = meniru budaya Barat; sekularisasi = memisahkan agama dari urusan duniawi. 2. Contoh: adat mengikat — solusinya pendekatan tokoh adat; pendidikan rendah — solusinya pemerataan sekolah; prasangka — solusinya literasi media. 3. Positif: akses informasi dan usaha online; negatif: kecanduan gawai dan penyebaran hoaks.$t$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $t$Tujuan Pembelajaran$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $t$Setelah belajar bab ini, kamu dapat menyebutkan anggota keluargamu, menghafal alamat rumahmu, menjelaskan cara merawat tubuh, dan mengetahui cara menjaga dirimu agar tetap aman setiap hari.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $t$Keluargaku$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $t$Keluarga adalah orang-orang tersayang yang tinggal bersamamu: ayah, ibu, kakak, adik, dan mungkin kakek atau nenek. Setiap anggota keluarga punya tugas: ayah dan ibu bekerja mencari nafkah, kakak membantu adik, dan kamu membantu dengan merapikan mainan sendiri. Keluarga yang rukun saling menyayangi dan membantu.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $t$Alamat Rumahku$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $t$Setiap rumah punya alamat: nama jalan, nomor rumah, nama desa atau kelurahan, dan kota. Menghafal alamat rumah itu penting! Jika kamu tersesat di pasar atau mal, kamu bisa memberi tahu alamatmu kepada petugas keamanan atau polisi agar bisa diantar pulang. Hafalkan juga nomor telepon ayah atau ibumu.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $t$Merawat Tubuhku$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$t$Mandi dua kali sehari agar badan bersih dan wangi.$t$, $t$Menggosok gigi pagi dan malam sebelum tidur.$t$, $t$Mencuci tangan dengan sabun sebelum makan dan sesudah bermain.$t$, $t$Memotong kuku seminggu sekali agar tidak kotor.$t$, $t$Makan makanan bergizi dan tidur cukup agar tumbuh sehat.$t$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $t$Menjaga Diriku Aman$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $t$Tubuhmu milikmu sendiri. Ada bagian tubuh yang tidak boleh disentuh orang lain kecuali ayah, ibu, atau dokter saat memeriksa dengan didampingi orang tua. Jika ada orang asing yang mengajakmu pergi atau membuatmu takut, berteriaklah "TIDAK!" dan segera lari mencari orang dewasa yang kamu kenal, lalu ceritakan kepada ayah, ibu, atau gurumu.$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $t$Latihan$t$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$t$Latihan: 1. Sebutkan anggota keluargamu yang tinggal serumah! 2. Sebutkan alamat rumahmu lengkap! 3. Sebutkan tiga cara merawat tubuhmu! 4. Apa yang harus kamu lakukan jika orang asing mengajakmu pergi?$t$, $t$Kunci jawaban: 1. (Jawaban sesuai keluarga masing-masing: ayah, ibu, kakak, adik) 2. (Jawaban sesuai alamat masing-masing) 3. Contoh: mandi, gosok gigi, cuci tangan 4. Menolak dengan tegas, lari mencari orang dewasa yang dikenal, dan menceritakannya kepada orang tua atau guru.$t$])));
